#include "EditorApp.h"
#include "Scene/SceneSerializer.h"
#include "Assets/AssetManager.h"
#include "Core/FileSystem.h"
#include "Core/Log.h"
#include <imgui.h>
#include <algorithm>
namespace Stardust {
void EditorApp::SelectHierarchy(EntityID e){auto& io=ImGui::GetIO();if(io.KeyShift&&m_EntityAnchor){auto a=std::find(m_PreviousHierarchyRows.begin(),m_PreviousHierarchyRows.end(),m_EntityAnchor),b=std::find(m_PreviousHierarchyRows.begin(),m_PreviousHierarchyRows.end(),e);if(a!=m_PreviousHierarchyRows.end()&&b!=m_PreviousHierarchyRows.end()){if(!io.KeyCtrl)m_EntitySelection.clear();if(a>b)std::swap(a,b);for(;a<=b;++a)if(std::find(m_EntitySelection.begin(),m_EntitySelection.end(),*a)==m_EntitySelection.end())m_EntitySelection.push_back(*a);}}else if(io.KeyCtrl){auto at=std::find(m_EntitySelection.begin(),m_EntitySelection.end(),e);if(at==m_EntitySelection.end())m_EntitySelection.push_back(e);else m_EntitySelection.erase(at);m_EntityAnchor=e;}else{m_EntitySelection={e};m_EntityAnchor=e;}m_Selected=m_EntitySelection.empty()?0:m_EntitySelection.back();m_InspectAsset=false;m_ScenePickPending=false;}
void EditorApp::SelectProject(const std::string& path,const std::vector<std::string>& order){auto& io=ImGui::GetIO();if(io.KeyShift&&!m_AssetAnchor.empty()){auto a=std::find(order.begin(),order.end(),m_AssetAnchor),b=std::find(order.begin(),order.end(),path);if(a!=order.end()&&b!=order.end()){if(!io.KeyCtrl)m_AssetSelection.clear();if(a>b)std::swap(a,b);for(;a<=b;++a)if(std::find(m_AssetSelection.begin(),m_AssetSelection.end(),*a)==m_AssetSelection.end())m_AssetSelection.push_back(*a);}}else if(io.KeyCtrl){auto at=std::find(m_AssetSelection.begin(),m_AssetSelection.end(),path);if(at==m_AssetSelection.end())m_AssetSelection.push_back(path);else m_AssetSelection.erase(at);m_AssetAnchor=path;}else{m_AssetSelection={path};m_AssetAnchor=path;}m_SelectedAsset=path;m_InspectAsset=true;m_ScenePickPending=false;}
void EditorApp::CopyEntities(){if(m_EntitySelection.empty()&&ActiveScene().Reg().Valid(m_Selected))m_EntitySelection={m_Selected};m_EntityClipboard=SceneSerializer::SelectionToJson(ActiveScene(),m_EntitySelection);}
void EditorApp::PasteEntities(){if(m_EntityClipboard.empty())return;m_EntitySelection=SceneSerializer::InstantiateSelection(ActiveScene(),m_EntityClipboard);m_Selected=m_EntitySelection.empty()?0:m_EntitySelection.back();m_InspectAsset=false;}
void EditorApp::DeleteEntities(){auto selection=m_EntitySelection;if(selection.empty())selection={m_Selected};for(auto e:selection)if(ActiveScene().Reg().Valid(e))ActiveScene().DestroyEntity(e);m_EntitySelection.clear();m_Selected=0;}
void EditorApp::DuplicateEntities(){CopyEntities();PasteEntities();}
void EditorApp::CopyAssets(){m_AssetClipboard=m_AssetSelection;if(m_AssetClipboard.empty()&&!m_SelectedAsset.empty())m_AssetClipboard={m_SelectedAsset};}
void EditorApp::PasteAssets(){namespace fs=std::filesystem;auto root=fs::weakly_canonical(m_ProjectRoot),dest=fs::weakly_canonical(m_ProjectCurrentDir);auto relative=dest.lexically_relative(root);if(relative.empty()||*relative.begin()=="..")return;std::vector<std::string> pasted;for(auto& asset:m_AssetClipboard)try{auto source=fs::weakly_canonical(AssetManager::ToAbsolute(asset));bool nested=false;for(auto& other:m_AssetClipboard)if(other!=asset){auto parent=fs::weakly_canonical(AssetManager::ToAbsolute(other));auto r=source.lexically_relative(parent);if(!r.empty()&&*r.begin()!="..")nested=true;}if(nested||!fs::exists(source))continue;if(fs::is_directory(source)){auto r=dest.lexically_relative(source);if(!r.empty()&&*r.begin()!="..")continue;}auto target=dest/source.filename();for(int i=1;fs::exists(target);++i)target=dest/fs::u8path(FileSystem::Utf8(source.stem())+" Copy "+std::to_string(i)+FileSystem::Utf8(source.extension()));fs::copy(source,target,fs::copy_options::recursive|fs::copy_options::skip_symlinks);pasted.push_back(AssetManager::ToRelative(target));}catch(const std::exception& e){SD_ERROR("Cannot paste asset: {}",e.what());}if(!pasted.empty()){m_AssetSelection=pasted;m_SelectedAsset=pasted.back();m_InspectAsset=true;}}
}
